from fractions import Fraction

possible_p = set()
C_range = [-2, -1, 0, 1, 2]

for c1 in C_range:
    for c2 in C_range:
        if c2 == 0:
            continue

        # p = -c1 / c2
        p_value = Fraction(-c1, c2)

        # Constraint: p must be positive
        if p_value > 0:
            possible_p.add(p_value)

print(sorted([p for p in possible_p if isinstance(p, Fraction)]))
